private val Blue=Color(0xFF0B5CAA); private val Teal=Color(0xFF0AA88F); private val Bg=Color(0xFFF6FAFC); private val Ink=Color(0xFF18324A); private val Red=Color(0xFFE74747)
private const val PREF="seniorlink"
enum class S { SPLASH,O1,O2,O3,LOGIN,CADASTRO,WELCOME,HOME,PERFIL,LOCAL,LEMBRETES,NOVO,SOS,APRENDER,DETALHE,CONTATOS,CONFIG }
data class Contact(val id:Long,val name:String,val phone:String,val relation:String)
data class Reminder(val id:Int,val title:String,val desc:String,val time:Long,val repeat:String,val active:Boolean)
data class Profile(val name:String="Maria Silva de Oliveira",val birth:String="12/03/1950",val blood:String="O+",val allergies:String="Dipirona",val meds:String="Pressão alta, Vitamina D",val conditions:String="Hipertensão, Diabetes tipo 2")
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{App()}}}

@Composable fun App(){
 val c=LocalContext.current; val p=remember{c.getSharedPreferences(PREF,0)}
 var s by remember{mutableStateOf(if(p.getBoolean("logged",false))S.HOME else S.SPLASH)}
 var profile by remember{mutableStateOf(loadProfile(p))}
 val contacts=remember{mutableStateListOf<Contact>().apply{addAll(loadContacts(p))}}
 val reminders=remember{mutableStateListOf<Reminder>().apply{addAll(loadReminders(p))}}
 var big by remember{mutableStateOf(p.getBoolean("big",false))}
 val location=rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){}
 val notify=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){}
 fun go(x:S){s=x}
 BackHandler(s!=S.HOME&&s!=S.SPLASH){s=S.HOME}
 MaterialTheme(colorScheme=lightColorScheme(primary=Blue,secondary=Teal,background=Bg,error=Red),typography=Typography(bodyLarge=Typography().bodyLarge.copy(fontSize=if(big)19.sp else 16.sp))){when(s){
  S.SPLASH->Splash({go(S.O1)},{go(S.LOGIN)})
  S.O1->Onboard("Cuidado hoje,\nmais liberdade amanhã","O SeniorLink ajuda você a estar sempre por perto, com segurança e praticidade.",1,{go(S.O2)},{go(S.LOGIN)})
  S.O2->Onboard("Localização em\ntempo real","Acompanhe a localização de quem você ama, com segurança e privacidade.",2,{go(S.O3)},{go(S.LOGIN)})
  S.O3->Onboard("Lembretes que\nfazem a diferença","Medicamentos, compromissos e muito mais. Tudo no tempo certo.",3,{go(S.LOGIN)},{go(S.LOGIN)})
  S.LOGIN->Login({e,pwd->if(e==p.getString("email","")&&pwd==p.getString("pwd","")){p.edit().putBoolean("logged",true).apply();go(S.HOME)}},{go(S.CADASTRO)},{p.edit().putBoolean("logged",true).apply();go(S.HOME)})
  S.CADASTRO->Cadastro({go(S.LOGIN)}){n,e,pwd->p.edit().putString("email",e).putString("pwd",pwd).putString("name",n).putBoolean("logged",true).apply();profile=profile.copy(name=n);saveProfile(p,profile);go(S.WELCOME)}
  S.WELCOME->Welcome{go(S.HOME)}
  S.HOME->Home(profile){go(it)}
  S.PERFIL->Profile(profile,{profile=it;saveProfile(p,it);go(S.HOME)},{go(S.HOME)},{go(S.CONTATOS)},{go(S.CONFIG)})
  S.LOCAL->Local({go(S.HOME)},{location.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION))})
  S.LEMBRETES->Lembretes(reminders,{go(S.HOME)},{go(S.NOVO)},{r->val i=reminders.indexOfFirst{it.id==r.id};if(i>=0)reminders[i]=r.copy(active=!r.active);saveReminders(p,reminders)},{r->reminders.removeAll{it.id==r.id};saveReminders(p,reminders)})
  S.NOVO->Novo({go(S.LEMBRETES)}){r->reminders.add(r);saveReminders(p,reminders);schedule(c,r);if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(c,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)notify.launch(Manifest.permission.POST_NOTIFICATIONS);go(S.LEMBRETES)}
  S.SOS->Sos(contacts,{go(S.HOME)},{go(S.CONTATOS)})
  S.APRENDER->Aprender({go(S.HOME)},{go(S.DETALHE)})
  S.DETALHE->Detalhe{go(S.APRENDER)}
  S.CONTATOS->Contatos(contacts,{go(S.HOME)}){l->contacts.clear();contacts.addAll(l);saveContacts(p,contacts)}
  S.CONFIG->Config(big,{big=it;p.edit().putBoolean("big",it).apply()},{go(S.HOME)},{go(S.PERFIL)},{go(S.CONTATOS)},{p.edit().putBoolean("logged",false).apply();go(S.LOGIN)})
 }}
}

