fun cDial(phone:String,c:Context){c.startActivity(Intent(Intent.ACTION_DIAL,Uri.parse("tel:\${Uri.encode(phone)}")))}
fun loadProfile(p:SharedPreferences)=Profile(p.getString("profile",null) ?: p.getString("name","Maria Silva de Oliveira").orEmpty())
fun saveProfile(p:SharedPreferences,x:Profile){p.edit().putString("profile",x.name).apply()}
fun loadContacts(p:SharedPreferences):List<Contact>{val a=JSONArray(p.getString("contacts","[]")!!);return buildList{for(i in 0 until a.length()){val o=a.getJSONObject(i);add(Contact(o.getLong("id"),o.getString("name"),o.getString("phone"),o.optString("relation")))}}}
fun saveContacts(p:SharedPreferences,l:List<Contact>){val a=JSONArray();l.forEach{x->a.put(JSONObject().apply{put("id",x.id);put("name",x.name);put("phone",x.phone);put("relation",x.relation)})};p.edit().putString("contacts",a.toString()).apply()}
fun loadReminders(p:SharedPreferences):List<Reminder>{val a=JSONArray(p.getString("reminders","[]")!!);return buildList{for(i in 0 until a.length()){val o=a.getJSONObject(i);add(Reminder(o.getInt("id"),o.getString("title"),o.optString("desc"),o.getLong("time"),o.optString("repeat"),o.optBoolean("active",true)))}}}
fun saveReminders(p:SharedPreferences,l:List<Reminder>){val a=JSONArray();l.forEach{x->a.put(JSONObject().apply{put("id",x.id);put("title",x.title);put("desc",x.desc);put("time",x.time);put("repeat",x.repeat);put("active",x.active)})};p.edit().putString("reminders",a.toString()).apply()}
fun schedule(c:Context,r:Reminder){val i=Intent(c,ReminderReceiver::class.java).apply{putExtra("id",r.id);putExtra("title",r.title);putExtra("desc",r.desc)};val pi=PendingIntent.getBroadcast(c,r.id,i,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);(c.getSystemService(Context.ALARM_SERVICE) as AlarmManager).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,r.time,pi)}
